INSERT INTO adhkar (context_code, category, text_ar, text_nl, text_en, how_to_apply_ar, how_to_apply_nl, how_to_apply_en, reward_ar, reward_nl, reward_en, guidance_ar, guidance_nl, guidance_en, repetitions, sort_order) VALUES
('poverty', 'state', '«اللَّهُمَّ أَطْعِمْ مَنْ أَطْعَمَنِي، وَاسْقِ مَنْ سَقَانِي»', 'O Allaah, voed wie mij heeft gevoed en geef te drinken aan wie mij te drinken heeft gegeven.', 'O Allaah, feed the one who fed me and give drink to the one who gave me drink.', 'يقوله الجائع إذا أطعمه أحد أو سقاه، جزاء ودعاء؛ قاله النبي صلى الله عليه وسلم لما شرب نصيبه من اللبن ليلة أضياف المقداد.', 'Zegt de hongerige wanneer iemand hem voedt of te drinken geeft, als dank en smeekbede; de Profeet (vrede en zegeningen zij met hem) zei het toen hij zijn deel van de melk dronk.', 'Said by the hungry when someone feeds or gives him drink, as thanks and supplication; the Prophet (peace and blessings be upon him) said it when he drank his share of the milk.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء من أطعمه غيره وسقاه', 'rampspoed', 'calamity', 1, 241),('poverty', 'state', '«أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ»', 'Mogen de vastenden bij jullie het vasten verbreken, mogen de vromen jullie voedsel eten en mogen de engelen voor jullie om zegeningen vragen.', 'May the fasting break their fast with you, may the righteous eat your food, and may the angels invoke blessings upon you.', 'يقوله الضيف الصائم وغيره إذا طعم عند قوم، بعد فراغه من الطعام، جهرا يُسمعهم؛ شكرا لهم ودعاء.', 'Zegt de vastende gast en anderen wanneer hij bij mensen eet, na afloop van de maaltijd, hoorbaar; als dank en smeekbede voor hen.', 'Said by the fasting guest and others when he eats at people''s, after finishing the meal, audibly; as thanks and supplication for them.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وإذا أفطر عند قوم قال', 'rampspoed', 'calamity', 1, 242),('poverty', 'state', '﴿رَبِّ إِنِّي لِمَا أَنزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ﴾', 'Vertaling van de betekenis: Mijn Heer, waarlijk, ik ben behoeftig aan al het goede dat U tot mij neerzendt [al-Qasas 24] — de smeekbede van Moesaa in zijn armoede.', 'Meaning: My Lord, indeed I am in need of whatever good You send down to me [al-Qasas 24] — the supplication of Moesaa in his poverty.', 'قالها موسى عليه السلام وهو جائع غريب لا يملك شيئا، فساق الله له الطعام والأهل والأمان؛ فيقولها المضطر مستحضرا افتقاره التام إلى ربه.', 'Moesaa (vrede zij met hem) zei het terwijl hij hongerig en als vreemdeling niets bezat, en Allaah bracht hem voedsel, gezin en veiligheid; de armoedige zegt het dus.', 'Moosaa (peace be upon him) said it while hungry, a stranger owning nothing, and Allaah brought him food, family and safety; so the destitute says it.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'عند الحاجة والفقر', 'rampspoed', 'calamity', 1, 243),('poverty', 'state', 'يستعف عن المسألة، ويستغني بالله، ويتصبر؛ مستحضرا قوله تعالى: ﴿وَاصْبِرْ وَمَا صَبْرُكَ إِلَّا بِاللَّهِ﴾ [النحل: 127]، وسائلا: ﴿رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا﴾', 'Men onthoudt zich van bedelen, zoekt onafhankelijkheid bij Allaah en oefent geduld — wie zich geduldig toont, die schenkt Allaah geduld; en niemand kreeg een gave beter en ruimer dan geduld.', 'One refrains from begging, seeks sufficiency in Allaah and practises patience — whoever shows patience, Allaah grants him patience; and none was given a gift better and vaster than patience.', 'فعلاج الفقر ثلاثي: دعاء الاستعاذة المتقدم، وعمل الكسب، وقلب مستعفف متصبر.', 'De genezing van armoede is drievoudig: de eerder genoemde smeekbede om toevlucht, het werk van verwerving, en een kuis, geduldig hart.', 'The cure for poverty is threefold: the aforementioned supplication of refuge, the work of earning, and a chaste, patient heart.', 'الوعد منصوص: يعفه الله، ويغنه الله، ويصبّره الله؛ والصبر أوسع العطايا.', 'De belofte is uitdrukkelijk: Allaah maakt hem kuis, verrijkt hem en schenkt hem geduld; en geduld is de ruimste van de gaven.', 'The promise is stated: Allaah makes him chaste, enriches him and grants him patience; and patience is the vastest of gifts.', 'عدة الله للمستعفف والمتصبر', 'rampspoed', 'calamity', 1, 244),('enemy_fear', 'state', '«اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ»', 'O Allaah, wij plaatsen U tegenover hun borsten (om hen af te weren) en wij zoeken toevlucht bij U tegen hun kwaad.', 'O Allaah, we place You before them (to repel them) and we seek refuge in You from their evils.', 'يقوله من خاف عدوا أو ظالما أو سلطانا جائرا، مستحضرا أن الله يدفع عنه من يجعله في نحره؛ أي: يقابله ويكفيه أمره.', 'Zegt wie een vijand, een onrechtpleger of een onrechtvaardige heerser vreest, zich bewust dat Allaah hem afweert die Hij tegenover hem plaatst.', 'Said by whoever fears an enemy, an oppressor or an unjust ruler, mindful that Allaah repels from him the one He sets against him.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'عند الخوف من قوم', 'rampspoed', 'calamity', 1, 245),('enemy_fear', 'state', '«حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ»', 'Allaah is ons genoeg, en Hij is de al-Beschermer, de beste Zaakwaarnemer (al-Wakiel) — gezegd door Ibraahiem in het vuur en door Muhammad (vrede en zegeningen zij met hen) toen men hen bang wilde maken.', 'Allaah is sufficient for us, and He is al-Wakeel (the best Disposer of affairs) — said by Ibraahiem in the fire and by Muhammad (peace be upon them) when people sought to frighten them.', 'تقال عند اشتداد الخوف من تجمع الأعداء وعند كل أمر عظيم يعجز عنه العبد، بقلب متوكل؛ فبها انقلب الصحابة بنعمة من الله وفضل لم يمسسهم سوء.', 'Zegt men bij het toenemen van de vrees voor het samentroepen van vijanden en bij elke grote zaak waartoe de dienaar niet in staat is, met een vertrouwend hart; ermee keerden de metgezellen terug met een gunst van Allaah.', 'Said upon the increase of fear at the massing of enemies and at every great matter beyond the servant, with a trusting heart; by it the companions returned with a favour from Allaah.', 'فضلها مبين في تتمة الآية: ﴿فَانقَلَبُوا بِنِعْمَةٍ مِّنَ اللَّهِ وَفَضْلٍ لَّمْ يَمْسَسْهُمْ سُوءٌ﴾.', 'Haar verdienste is toegelicht in het vervolg van het vers: ''Zo keerden zij terug met een gunst van Allaah en een genade; geen kwaad raakte hen.''', 'Its merit is explained in the continuation of the verse: ''So they returned with a favour from Allaah and a bounty; no harm touched them.''', 'عند الخوف والتوكل', 'rampspoed', 'calamity', 1, 246),('enemy_fear', 'state', '«اللَّهُمَّ مُنْزِلَ الْكِتَابِ، سَرِيعَ الْحِسَابِ، اهْزِمِ الْأَحْزَابَ، اللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ»', 'O Allaah, Neerzender van het Boek, Snel in de afrekening: versla de bondgenoten. O Allaah, versla hen en doe hen beven.', 'O Allaah, Revealer of the Book, Swift in reckoning: defeat the confederates. O Allaah, defeat them and shake them.', 'يدعو به المجاهدون عند الملاقاة، ومن سنته صلى الله عليه وسلم أنه كان إذا غزا قوما انتظر حتى تميل الشمس ثم قاتل ودعا.', 'Smeken de strijders bij de ontmoeting; en het behoort tot zijn soennah (vrede en zegeningen zij met hem) dat hij, wanneer hij een volk bestreed, wachtte tot de zon overhelde.', 'Supplicated by the fighters upon meeting; and it is of his sunnah (peace and blessings be upon him) that when he fought a people he waited until the sun declined.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء لقاء العدو في القتال', 'rampspoed', 'calamity', 1, 247),('enemy_fear', 'state', '«لَا تَتَمَنَّوْا لِقَاءَ الْعَدُوِّ، وَسَلُوا اللَّهَ الْعَافِيَةَ، فَإِذَا لَقِيتُمُوهُمْ فَاصْبِرُوا»', 'Wenst de ontmoeting met de vijand niet, maar vraagt Allaah om welzijn; en wanneer jullie hen treffen, wees dan standvastig — en weet dat het Paradijs onder de schaduw van de zwaarden ligt.', 'Do not wish to meet the enemy, but ask Allaah for wellbeing; and when you meet them, stand firm — and know that Paradise lies beneath the shade of the swords.', 'فالتطبيق قبل النازلة: سؤال الله العافية ودوامها، وعند وقوعها: الصبر والثبات مع الدعاء.', 'De toepassing vóór de rampspoed: Allaah om welzijn en het voortduren ervan vragen; en bij het optreden ervan: geduld en standvastigheid met smeekbede.', 'The application before calamity: asking Allaah for wellbeing and its continuance; and upon its occurrence: patience and steadfastness with supplication.', 'فيه بيان أن سؤال العافية مقدَّم قبل النازلة، والصبر فريضة عند وقوعها.', 'Daarin ligt de verklaring dat het vragen van welzijn voorafgaat aan de rampspoed, en dat geduld verplicht is wanneer zij optreedt.', 'In it is the explanation that asking wellbeing precedes calamity, and that patience is obligatory when it befalls.', 'ولا يُتمنى لقاء العدو', 'rampspoed', 'calamity', 1, 248),('eclipse', 'event', '«إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ، لَا يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ، فَإِذَا رَأَيْتُمْ ذَلِكَ فَادْعُوا اللَّهَ، وَكَبِّرُوا، وَصَلُّوا، وَتَصَدَّقُوا»', 'De zon en de maan zijn twee tekenen van Allaah; zij verduisteren niet wegens iemands dood of leven. Zien jullie dat, smeek dan Allaah, zeg takbier, bid en geef liefdadigheid.', 'The sun and the moon are two signs of Allaah; they do not eclipse for anyone''s death or life. When you see that, supplicate Allaah, say takbeer, pray and give charity.', 'فالتطبيق أربعة أعمال تبتدأ فور رؤية الكسوف وتستمر حتى ينجلي: الدعاء، والتكبير، وصلاة الكسوف جماعة بركوعين في كل ركعة، والصدقة، ويضاف إليها العتق كما في البخاري (1054).', 'De toepassing is vier handelingen die direct bij het zien van de eclips beginnen en voortduren tot zij opklaart: de smeekbede, de takbier, het eclipsgebed in gemeenschap, en de liefdadigheid.', 'The application is four acts beginning at once upon seeing the eclipse and continuing until it clears: supplication, takbeer, the eclipse prayer in congregation, and charity.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'ما يُفعل عند كسوف الشمس أو خسوف القمر', 'rampspoed', 'calamity', 1, 249),('eclipse', 'event', '«فَإِذَا رَأَيْتُمْ شَيْئًا مِنْ ذَلِكَ فَافْزَعُوا إِلَى ذِكْرِهِ وَدُعَائِهِ وَاسْتِغْفَارِهِ»', 'Zien jullie iets daarvan, haast jullie dan naar Zijn gedenken, Zijn smeekbede en het vragen van Zijn vergeving.', 'When you see any of that, hasten to His remembrance, His supplication and seeking His forgiveness.', 'فيُشرع الإكثار من الاستغفار خاصة؛ لأن الكسوف تخويف من الله يناسبه الرجوع والتوبة، ولم يثبت دعاء مؤقت بلفظ معين للكسوف.', 'Het vermeerderen van istighfaar in het bijzonder is voorgeschreven; want de eclips is een waarschuwing van Allaah die past bij terugkeer en berouw, en er is geen vaste smeekbede overgeleverd.', 'Increasing istighfaar in particular is prescribed; for the eclipse is a warning from Allaah suited to return and repentance, and no fixed supplication is transmitted.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'ويفزع إلى ذكر الله', 'rampspoed', 'calamity', 1, 250),('epidemic', 'state', '«اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبَرَصِ وَالْجُنُونِ وَالْجُذَامِ، وَمِنْ سَيِّئِ الْأَسْقَامِ»', 'O Allaah, ik zoek toevlucht bij U tegen huidziekte (lepra-vlekken), waanzin en melaatsheid, en tegen de kwade ziekten.', 'O Allaah, I seek refuge in You from leprosy, madness and elephantiasis, and from evil diseases.', 'يجعل من دعائه الراتب في الصباح والمساء وسائر الأحوال، ويتأكد عند انتشار الأوبئة والأمراض.', 'Men maakt het tot zijn vaste smeekbede in de ochtend, de avond en overige toestanden, en het wordt nadrukkelijker bij het uitbreken van epidemieën en ziekten.', 'One makes it a regular supplication in the morning, evening and other states, and it becomes more emphatic when epidemics and diseases spread.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الاستعاذة من الأمراض المنكرة', 'rampspoed', 'calamity', 1, 251),('epidemic', 'state', '«لَيْسَ مِنْ عَبْدٍ يَقَعُ الطَّاعُونُ فَيَمْكُثُ فِي بَلَدِهِ صَابِرًا مُحْتَسِبًا، يَعْلَمُ أَنَّهُ لَا يُصِيبُهُ إِلَّا مَا كَتَبَ اللَّهُ لَهُ، إِلَّا كَانَ لَهُ مِثْلُ أَجْرِ شَهِيدٍ»', 'Geen dienaar blijft bij een pestuitbraak geduldig en op beloning hopend in zijn stad, wetend dat hem slechts treft wat Allaah voor hem heeft beschikt, of hij krijgt de beloning van een martelaar.', 'No servant remains patiently in his town during a plague, hoping for reward and knowing only what Allaah decreed will befall him, except that he has the reward of a martyr.', 'فالتطبيق عند الوباء: البقاء في البلد وعدم الفرار، مع الصبر والاحتساب واليقين بالقدر، ويلازم أذكار الصباح والمساء التي فيها الحفظ، ودعاء رؤية المبتلى المتقدم.', 'De toepassing bij een epidemie: in het land blijven en niet vluchten, met geduld, hoop op beloning en zekerheid over het lot, en men houdt vast aan de adhkaar (van bescherming).', 'The application during an epidemic: remaining in the land and not fleeing, with patience, hope of reward and certainty in the decree, holding to the adhkaar (of protection).', 'الأجر منصوص: مثل أجر شهيد لمن مكث صابرا محتسبا.', 'De beloning is uitdrukkelijk: gelijk aan de beloning van een martelaar voor wie geduldig en op beloning hopend (in zijn stad) blijft.', 'The reward is stated: like the reward of a martyr for whoever remains patient and hoping for reward.', 'ما يقول ويفعل من وقع الطاعون بأرضه', 'rampspoed', 'calamity', 1, 252),('stings', 'state', '«مَنْ قَالَ حِينَ يُمْسِي ثَلَاثَ مَرَّاتٍ: أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ، لَمْ تَضُرَّهُ حُمَةُ تِلْكَ اللَّيْلَةِ»', 'Ik zoek toevlucht bij de volmaakte Woorden van Allaah tegen het kwade van wat Hij heeft geschapen (driemaal in de avond; dan schaadt geen gifsteek die nacht).', 'I seek refuge in the perfect Words of Allaah from the evil of what He created (three times in the evening; then no sting will harm that night).', 'يقوله كل مساء ثلاثا؛ فهو حرز من لدغ العقارب والحيات وذوات السموم، وقاله صلى الله عليه وسلم لمن شكا لدغة عقرب: «أما لو قلتَ حين أمسيت لم تضرك».', 'Zegt men elke avond driemaal; het is een bescherming tegen de steek van schorpioenen, slangen en giftige dieren, en hij (vrede en zegeningen zij met hem) zei het tegen wie erover klaagde.', 'Said three times every evening; it is a protection from the sting of scorpions, snakes and venomous creatures, and he (peace and blessings be upon him) said it to whoever complained of it.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'في المساء للوقاية', 'rampspoed', 'calamity', 1, 253),('stings', 'state', 'رَقَى أَبُو سَعِيدٍ الْخُدْرِيُّ رَضِيَ اللَّهُ عَنْهُ سَيِّدَ الْحَيِّ اللَّدِيغَ بِفَاتِحَةِ الْكِتَابِ فَبَرَأَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «وَمَا يُدْرِيكَ أَنَّهَا رُقْيَةٌ؟»', 'Aboe Sa3ied (moge Allaah tevreden over hem zijn) verrichtte roeqyah over de gestoken stamleider met soerah al-Faatihah, en hij herstelde alsof hij van een band was losgemaakt.', 'Aboo Sa3eed (may Allaah be pleased with him) performed ruqyah over the stung chief with soorah al-Faatihah, and he recovered as if released from a tether.', 'التطبيق: تقرأ الفاتحة على اللديغ ــ وفي الرواية أنه قرأها سبع مرات ويجمع ريقه ويتفل ــ مع الأخذ بأسباب العلاج الطبي؛ فالرقية لا تنافي التداوي.', 'De toepassing: men leest al-Faatihah over de gestokene — in de overlevering zevenmaal, waarbij men speeksel verzamelt en licht blaast — met het nemen van de (medische) middelen.', 'The application: one reads al-Faatihah over the stung person — in the narration seven times, gathering saliva and blowing lightly — while taking the (medical) means.', 'الفضل مبين في القصة: برئ اللديغ بها كأنما نُشط من عقال، وأقر النبي صلى الله عليه وسلم أنها رقية.', 'De verdienste is toegelicht in het verhaal: de gestokene genas ermee alsof hij van een band werd losgemaakt, en de Profeet (vrede en zegeningen zij met hem) bevestigde dat het een roeqyah is.', 'The merit is explained in the account: the stung man was cured by it as if released from a tether, and the Prophet (peace and blessings be upon him) confirmed it is a ruqyah.', 'رقية اللديغ بفاتحة الكتاب', 'rampspoed', 'calamity', 1, 254),('night_fright', 'state', '«أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ»', 'Ik zoek toevlucht bij de volmaakte Woorden van Allaah tegen Zijn toorn en Zijn bestraffing, tegen het kwade van Zijn dienaren, en tegen de influisteringen van de shayaatien en dat zij bij mij komen.', 'I seek refuge in the perfect Words of Allaah from His anger and His punishment, from the evil of His servants, and from the whisperings of the devils and lest they be present with me.', 'كان عبد الله بن عمرو رضي الله عنهما يعلّمها من بلغ من ولده يقولها عند نومه، ويكتبها فيعلقها على من لم يبلغ ــ والمحفوظ التعليم دون التعليق ــ فتقال عند الفزع في النوم وعند النوم لمن يعتاده الفزع.', '3abdullaah ibn 3amr (moge Allaah tevreden over hen zijn) onderwees ze aan zijn kinderen die de leeftijd bereikten om ze bij het slapen te zeggen, en schreef ze op voor wie (nog) niet kon.', '3abdullaah ibn 3amr (may Allaah be pleased with them) taught them to his children who reached the age to say them at sleep, and wrote them down for whoever could not (yet).', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'من فزع في نومه فليقل', 'toestand', 'state/situation', 1, 255),('khutbah', 'event', '«إِنَّ الْحَمْدَ لِلَّهِ، نَحْمَدُهُ وَنَسْتَعِينُهُ وَنَسْتَغْفِرُهُ، وَنَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَيِّئَاتِ أَعْمَالِنَا، مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ، وَمَنْ يُضْلِلْ فَلَا هَادِيَ لَهُ، وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ»', 'Waarlijk, alle lof zij Allaah: wij prijzen Hem, vragen Hem om hulp en om vergeving, en wij zoeken toevlucht bij Allaah tegen het kwade van onszelf en de slechtheid van onze daden. Wie Allaah leidt, niemand kan hem doen dwalen; en wie Hij laat dwalen, niemand kan hem leiden. Ik getuig dat er geen god is behalve Allaah, en ik getuig dat Muhammad Zijn dienaar en boodschapper is (khutbat al-haadjah, waarna de drie verzen).', 'Indeed all praise is for Allaah: we praise Him, seek His help and His forgiveness, and we seek refuge in Allaah from the evil of ourselves and from our bad deeds. Whomever Allaah guides, none can misguide; and whomever He leaves astray, none can guide. I bear witness that none has the right to be worshipped except Allaah, and that Muhammad is His slave and messenger (khutbat al-haajah, followed by the three verses).', 'يفتتح بها خطبة النكاح والجمعة والدروس والمحاضرات وصدور الكتب؛ يقولها ثم يشرع في حاجته التي قام لها.', 'Men opent er de huwelijks-, vrijdags-, lessen- en lezingenkhutbah en de voorwoorden van boeken mee; men zegt haar en begint dan met zijn zaak.', 'One opens the marriage, Friday, lesson and lecture khutbah and the prefaces of books with it; one says it then begins with one''s matter.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'كان النبي ﷺ يعلّم أصحابه خطبة الحاجة', 'gelegenheid', 'occasion', 1, 256),('first_fruits', 'life', '«اللَّهُمَّ بَارِكْ لَنَا فِي ثَمَرِنَا، وَبَارِكْ لَنَا فِي مَدِينَتِنَا، وَبَارِكْ لَنَا فِي صَاعِنَا، وَبَارِكْ لَنَا فِي مُدِّنَا»', 'O Allaah, zegen ons in onze vruchten, zegen ons in onze stad, zegen ons in onze saa3 en zegen ons in onze mudd (maten).', 'O Allaah, bless us in our fruits, bless us in our city, bless us in our saa3 and bless us in our mudd (measures).', 'فيُدعى بالبركة عند أول ثمر الموسم ونحوه من أوائل الأرزاق، ويُعطى الصغار منه إدخالا للسرور.', 'Men vraagt om zegen bij de eerste vrucht van het seizoen en dergelijke eerstelingen van de voorziening, en men geeft ervan aan de kleinen om hen vreugde te schenken.', 'One asks for blessing at the season''s first fruit and such firstlings of provision, and gives of it to the young to bring them joy.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'كان الناس إذا رأوا أول', 'gelegenheid', 'occasion', 1, 257),('slaughter', 'life', 'ضَحَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِكَبْشَيْنِ أَمْلَحَيْنِ أَقْرَنَيْنِ، ذَبَحَهُمَا بِيَدِهِ، وَسَمَّى وَكَبَّرَ: «بِسْمِ اللَّهِ، وَاللَّهُ أَكْبَرُ»', 'Hij offerde twee gehoornde, zwart-witte rammen: hij slachtte ze eigenhandig, sprak de tasmiyah en de takbier uit en zette zijn voet op hun flanken.', 'He sacrificed two horned black-and-white rams: slaughtering them himself, saying the tasmiyah and takbeer, placing his foot on their sides.', 'فيقول الذابح عند إمرار الشفرة: «بسم الله، والله أكبر»، والتسمية شرط، والتكبير سنة.', 'De slachtende zegt bij het halen van het mes: ''In de Naam van Allaah, Allaah is de Grootste''; de tasmiyah is voorwaarde, de takbier soennah.', 'The slaughterer says on drawing the blade: ''In the Name of Allaah, Allaah is the Greatest''; the tasmiyah is a condition, the takbeer a sunnah.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'التسمية والتكبير عند الذبح', 'gelegenheid', 'occasion', 1, 258),('slaughter', 'life', '«بِسْمِ اللَّهِ، اللَّهُمَّ تَقَبَّلْ مِنْ مُحَمَّدٍ وَآلِ مُحَمَّدٍ وَمِنْ أُمَّةِ مُحَمَّدٍ»', 'In de Naam van Allaah. O Allaah, aanvaard van Muhammad en de familie van Muhammad, en van de ummah van Muhammad (en men noemt bij het offer zijn eigen naam).', 'In the Name of Allaah. O Allaah, accept from Muhammad and the family of Muhammad, and from the ummah of Muhammad (naming oneself at one''s own sacrifice).', 'فيسمي المضحي نفسه وأهله: «اللهم تقبل من فلان وآل فلان» عند الذبح.', 'De offeraar noemt zichzelf en zijn gezin: ''O Allaah, aanvaard van die-en-die en de familie van die-en-die'' bij het slachten.', 'The one sacrificing names himself and his family: ''O Allaah, accept from so-and-so and the family of so-and-so'' at slaughter.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'ويقول في الأضحية', 'gelegenheid', 'occasion', 1, 259),('arafah', 'event', '«لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ»', 'Niets of niemand heeft het recht aanbeden te worden behalve Allaah, alleen, zonder deelgenoot. Aan Hem behoort de heerschappij en aan Hem behoort alle lof, en Hij is tot alles in staat.', 'None has the right to be worshipped except Allaah alone, without partner. His is the dominion and His is all praise, and He is able to do all things.', 'يُكثر منه الحاج بعرفة من الزوال إلى الغروب رافعا يديه مستقبل القبلة، ويُكثر منه غير الحاج في يومه؛ فالفضل لليوم.', 'De bedevaartganger vermeerdert het te 3arafah van de middag tot zonsondergang, met opgeheven handen richting de qiblah, en de niet-bedevaartganger op zijn (vasten)dag.', 'The pilgrim increases it at 3arafah from midday to sunset, hands raised toward the qiblah, and the non-pilgrim on his (fasting) day.', 'الفضل منصوص: خير الدعاء، وخير ما قاله النبيون.', 'De verdienste is uitdrukkelijk: de beste smeekbede, en het beste wat de profeten zeiden.', 'The merit is stated: the best supplication, and the best that the prophets said.', 'التهليل يوم عرفة', 'jaarlijkse periode', 'yearly season', 1, 260);